import React, { useEffect, useState, useCallback } from 'react';
import reservationService from '../../services/reservationService';
import roomService from '../../services/roomService';
import clientService from '../../services/clientService';
import PageHeader from '../../components/common/PageHeader';
import DataTable from '../../components/common/DataTable';
import Modal from '../../components/common/Modal';
import StatusBadge from '../../components/common/StatusBadge';
import '../../components/common/shared.css';

const EMPTY_FORM = {
  client_id: '', room_id: '', check_in: '', check_out: '', guests: 1, notes: '',
};

const ReservationForm = ({ initial = EMPTY_FORM, clients, rooms, onSubmit, onClose, loading }) => {
  const [form, setForm]   = useState(initial);
  const [errors, setErrors] = useState({});

  const validate = () => {
    const e = {};
    if (!form.client_id) e.client_id = 'Client requis';
    if (!form.room_id)   e.room_id   = 'Chambre requise';
    if (!form.check_in)  e.check_in  = 'Date arrivée requise';
    if (!form.check_out) e.check_out = 'Date départ requise';
    return e;
  };

  const handle = ({ target: { name, value } }) => {
    setForm(p => ({ ...p, [name]: value }));
    if (errors[name]) setErrors(p => ({ ...p, [name]: '' }));
  };

  const submit = (e) => {
    e.preventDefault();
    const e2 = validate();
    if (Object.keys(e2).length) { setErrors(e2); return; }
    onSubmit(form);
  };

  return (
    <form onSubmit={submit}>
      <div className="form-grid">
        <div className="form-group">
          <label className="form-label">Client *</label>
          <select name="client_id" className="form-select" value={form.client_id} onChange={handle}>
            <option value="">Sélectionner…</option>
            {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
          </select>
          {errors.client_id && <span className="form-error">{errors.client_id}</span>}
        </div>
        <div className="form-group">
          <label className="form-label">Chambre *</label>
          <select name="room_id" className="form-select" value={form.room_id} onChange={handle}>
            <option value="">Sélectionner…</option>
            {rooms.map(r => <option key={r.id} value={r.id}>Chambre {r.number} — {r.type}</option>)}
          </select>
          {errors.room_id && <span className="form-error">{errors.room_id}</span>}
        </div>
        <div className="form-group">
          <label className="form-label">Arrivée *</label>
          <input type="date" name="check_in" className="form-input" value={form.check_in} onChange={handle} />
          {errors.check_in && <span className="form-error">{errors.check_in}</span>}
        </div>
        <div className="form-group">
          <label className="form-label">Départ *</label>
          <input type="date" name="check_out" className="form-input" value={form.check_out} onChange={handle} />
          {errors.check_out && <span className="form-error">{errors.check_out}</span>}
        </div>
        <div className="form-group">
          <label className="form-label">Personnes</label>
          <input type="number" name="guests" className="form-input" value={form.guests} min={1} max={10} onChange={handle} />
        </div>
        <div className="form-group">
          <label className="form-label">Statut</label>
          <select name="status" className="form-select" value={form.status ?? ''} onChange={handle}>
            <option value="">— inchangé —</option>
            {['pending','confirmed','checked_in','checked_out','cancelled'].map(s => (
              <option key={s} value={s}>{s}</option>
            ))}
          </select>
        </div>
      </div>
      <div className="form-group" style={{ marginTop: '1rem' }}>
        <label className="form-label">Notes</label>
        <textarea name="notes" className="form-textarea" value={form.notes} onChange={handle} placeholder="Remarques…" />
      </div>
      <div className="form-actions">
        <button type="button" className="btn btn--outline" onClick={onClose}>Annuler</button>
        <button type="submit" className="btn btn--primary" disabled={loading}>
          {loading ? <span className="dt-spinner" /> : 'Enregistrer'}
        </button>
      </div>
    </form>
  );
};

const ReservationsPage = () => {
  const [reservations, setReservations] = useState([]);
  const [clients, setClients]           = useState([]);
  const [rooms, setRooms]               = useState([]);
  const [loading, setLoading]           = useState(true);
  const [modal, setModal]               = useState(null);
  const [saving, setSaving]             = useState(false);
  const [statusFilter, setStatusFilter] = useState('');

  const load = useCallback(() => {
    setLoading(true);
    Promise.allSettled([
      reservationService.getAll(),
      clientService.getAll(),
      roomService.getAll(),
    ]).then(([r, c, ro]) => {
      if (r.status === 'fulfilled')  setReservations(r.value);
      if (c.status === 'fulfilled')  setClients(c.value);
      if (ro.status === 'fulfilled') setRooms(ro.value);
      setLoading(false);
    });
  }, []);

  useEffect(() => { load(); }, [load]);

  const handleCreate = async (form) => {
    setSaving(true);
    try { await reservationService.create(form); setModal(null); load(); }
    catch (err) { alert(err.message); }
    finally { setSaving(false); }
  };

  const handleEdit = async (form) => {
    setSaving(true);
    try { await reservationService.update(modal.res.id, form); setModal(null); load(); }
    catch (err) { alert(err.message); }
    finally { setSaving(false); }
  };

  const handleCancel = async (id) => {
    if (!window.confirm('Annuler cette réservation ?')) return;
    try { await reservationService.cancel(id); load(); }
    catch (err) { alert(err.message); }
  };

  const filtered = statusFilter
    ? reservations.filter(r => r.status === statusFilter)
    : reservations;

  const columns = [
    { key: 'id', label: '#', render: r => `#${r.id}` },
    { key: 'client', label: 'Client', render: r => r.client?.name ?? `#${r.client_id}` },
    { key: 'room',   label: 'Chambre', render: r => `Ch. ${r.room?.number ?? r.room_id}` },
    { key: 'check_in',  label: 'Arrivée',  render: r => new Date(r.check_in).toLocaleDateString('fr-FR') },
    { key: 'check_out', label: 'Départ',   render: r => new Date(r.check_out).toLocaleDateString('fr-FR') },
    { key: 'status', label: 'Statut', render: r => <StatusBadge status={r.status} /> },
  ];

  return (
    <div>
      <PageHeader
        title="Gestion des réservations"
        subtitle={`${reservations.length} réservation${reservations.length > 1 ? 's' : ''} au total`}
        action={
          <button className="btn btn--primary" onClick={() => setModal('create')}>
            + Nouvelle réservation
          </button>
        }
      />

      <div style={{ marginBottom: '1rem', display: 'flex', gap: '1rem', flexWrap: 'wrap' }}>
        {['', 'pending', 'confirmed', 'checked_in', 'checked_out', 'cancelled'].map(s => (
          <button
            key={s}
            className={`btn btn--sm ${statusFilter === s ? 'btn--primary' : 'btn--outline'}`}
            onClick={() => setStatusFilter(s)}
          >
            {s === '' ? 'Tous' : <StatusBadge status={s} />}
          </button>
        ))}
      </div>

      <DataTable
        columns={columns}
        data={filtered}
        loading={loading}
        empty="Aucune réservation."
        actions={row => (
          <div style={{ display: 'flex', gap: 6 }}>
            <button
              className="btn btn--sm btn--outline"
              onClick={() => setModal({ type: 'edit', res: row })}
            >
              Modifier
            </button>
            {!['cancelled','checked_out'].includes(row.status) && (
              <button
                className="btn btn--sm btn--danger"
                onClick={() => handleCancel(row.id)}
              >
                Annuler
              </button>
            )}
          </div>
        )}
      />

      {modal === 'create' && (
        <Modal title="Nouvelle réservation" onClose={() => setModal(null)} size="lg">
          <ReservationForm
            clients={clients} rooms={rooms}
            onSubmit={handleCreate} onClose={() => setModal(null)} loading={saving}
          />
        </Modal>
      )}

      {modal?.type === 'edit' && (
        <Modal title="Modifier la réservation" onClose={() => setModal(null)} size="lg">
          <ReservationForm
            initial={modal.res}
            clients={clients} rooms={rooms}
            onSubmit={handleEdit} onClose={() => setModal(null)} loading={saving}
          />
        </Modal>
      )}
    </div>
  );
};

export default ReservationsPage;
